// Dans src/pages/dashboard/components/CoursesTab.js
import React, { useState } from 'react';
import CourseDetailAdmin from './CourseDetailAdmin';

const CoursesTab = ({ courses, onNewCourse, onDeleteCourse }) => {
  const [selectedCourseId, setSelectedCourseId] = useState(null);
  const [showDetailAdmin, setShowDetailAdmin] = useState(false);

  const handleEditCourse = (courseId) => {
    setSelectedCourseId(courseId);
    setShowDetailAdmin(true);
  };

  const handleCloseDetailAdmin = () => {
    setSelectedCourseId(null);
    setShowDetailAdmin(false);
  };

  const handleUpdateCourse = () => {
    // Rafraîchir les données si nécessaire
    console.log('Cours mis à jour');
  };

  return (
    <div className="courses-tab">
      <div className="tab-header">
        <h2>Gestion des Cours ({courses.length} cours)</h2>
        <button 
          className="btn btn-primary"
          onClick={onNewCourse}
        >
          + Nouveau Cours
        </button>
      </div>

      {/* Tableau des cours */}
      <div className="table-container">
        <table className="data-table">
          <thead>
            <tr>
              <th>Titre</th>
              <th>Catégorie</th>
              <th>Formateur</th>
              <th>Prix</th>
              <th>Apprenants</th>
              <th>Note</th>
              <th>Statut</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {courses.map(course => (
              <tr key={course.id}>
                <td>
                  <div className="course-cell">
                    <div className="course-thumb-placeholder">
                      <img 
                        src={course.image} 
                        alt={course.title}
                        onError={(e) => {
                          e.target.src = '/images/default-course.jpg';
                        }}
                      />
                    </div>
                    <div>
                      <strong>{course.title}</strong>
                      <p className="course-description">
                        {course.description?.substring(0, 50)}...
                      </p>
                    </div>
                  </div>
                </td>
                <td>{course.category}</td>
                <td>{course.instructor}</td>
                <td>
                  {course.hasPromotion ? (
                    <>
                      <del>{course.originalPrice} TND</del>
                      <br />
                      <strong style={{color: '#e91e63'}}>
                        {course.price} TND
                      </strong>
                    </>
                  ) : (
                    <strong>{course.price} TND</strong>
                  )}
                </td>
                <td>{course.students || 0}</td>
                <td>
                  <div className="rating-display">
                    <span className="stars">⭐</span>
                    <span>{course.rating || 4.5}/5</span>
                  </div>
                </td>
                <td>
                  <span className={`status-badge ${course.status}`}>
                    {course.status === 'published' ? 'Publié' : 'Brouillon'}
                  </span>
                </td>
                <td>
                  <div className="action-buttons">
                    <button 
                      className="btn-action btn-view"
                      onClick={() => handleEditCourse(course.id)}
                      title="Modifier le cours"
                    >
                      ✏️ Modifier
                    </button>
                    <button 
                      className="btn-action btn-danger"
                      onClick={() => onDeleteCourse(course.id)}
                      title="Supprimer le cours"
                    >
                      🗑️
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modal de gestion détaillée */}
      {showDetailAdmin && selectedCourseId && (
        <CourseDetailAdmin 
          courseId={selectedCourseId}
          onClose={handleCloseDetailAdmin}
          onUpdate={handleUpdateCourse}
        />
      )}
    </div>
  );
};

export default CoursesTab;
